using BetaFit.Desktop.Models;using BetaFit.Desktop.Services;
namespace BetaFit.Desktop.Forms;
public sealed class FrmCategoryForm:Form {private readonly IBetaFitApiService _api;private readonly Guid? _id;private readonly TextBox name=new(),desc=new(),image=new();public FrmCategoryForm(IBetaFitApiService api,Guid? id){_api=api;_id=id;Text=id.HasValue?"Editar categoria":"Nova categoria";StartPosition=FormStartPosition.CenterParent;ClientSize=new Size(540,390);BackColor=Color.FromArgb(15,18,23);name.PlaceholderText="Nome";desc.PlaceholderText="Descrição";desc.Multiline=true;desc.Height=100;image.PlaceholderText="Imagem URL";var save=new Button{Text="Salvar",Width=110,Height=40};var cancel=new Button{Text="Cancelar",Width=110,Height=40};var flow=new FlowLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(35),FlowDirection=FlowDirection.TopDown,WrapContents=false};foreach(var c in new Control[]{name,desc,image,save,cancel}){c.Width=450;c.Margin=new Padding(0,0,0,12);flow.Controls.Add(c);}Controls.Add(flow);cancel.Click+=(_,_)=>Close();save.Click+=async(_,_)=>await SaveAsync();Load+=async(_,_)=>await LoadAsync();}private async Task LoadAsync(){if(!_id.HasValue)return;try{var c=(await _api.GetCategoriesAsync()).FirstOrDefault(x=>x.Id==_id);if(c!=null){name.Text=c.Name;desc.Text=c.Description;image.Text=c.ImageUrl??"";}}catch(Exception ex){MessageBox.Show(ex.Message,"BetaFit",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}private async Task SaveAsync(){if(string.IsNullOrWhiteSpace(name.Text)){MessageBox.Show("Nome obrigatório.");return;}try{if(_id.HasValue)await _api.UpdateCategoryAsync(_id.Value,new UpdateCategoryRequest{Name=name.Text.Trim(),Description=desc.Text.Trim(),ImageUrl=string.IsNullOrWhiteSpace(image.Text)?null:image.Text.Trim()});else await _api.CreateCategoryAsync(new CreateCategoryRequest{Name=name.Text.Trim(),Description=desc.Text.Trim(),ImageUrl=string.IsNullOrWhiteSpace(image.Text)?null:image.Text.Trim()});DialogResult=DialogResult.OK;Close();}catch(Exception ex){MessageBox.Show(ex.Message,"BetaFit",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}}